import React from "react";
const TABLE_HTML = "<table><thead><tr><th>Person / role</th><th>What this person must do</th><th>Evidence / hand-off</th></tr></thead><tbody>\n<tr><td>Warehouse supervisor</td><td>Locate the correct fabric lot. Confirm roll count and identity. Arrange the required percentage of rolls and their movement to the inspector.</td><td>Lot location, selected roll list and roll delivery to inspection.</td></tr>\n<tr><td>Fabric inspection supervisor<br><span style=\"font-weight:400;color:#607587\">Functional role in this sample</span></td><td>Review merchandising quality requirements and buyer comments from sample development. Confirm inspection scope, grading method, tolerances and escalation instructions before work starts.</td><td>Current inspection brief; buyer requirements and sample comments communicated to inspector.</td></tr>\n<tr><td>Warehouse quality controller</td><td>Review product-development and sample comments. Identify concerns to watch for, such as shade, appearance or previously reported defects. Check that the correct approved references are available.</td><td>Quality concerns/checklist handed to inspector; discrepancies escalated.</td></tr>\n<tr><td>Fabric inspector</td><td>Obtain approved fabric reference, approved colour cards and controlled documents. Verify roll IDs. Clean the inspection machine, check its condition, lighting, speed and measurement setup against the work instruction. Inspect and record defects, locations, points, width, length and shade findings.</td><td>Roll-by-roll inspection record, measured results, defect evidence and exceptions.</td></tr>\n<tr><td>Warehouse workers / handling support</td><td>Bring the selected rolls, support loading/unloading and return identified rolls to the correct area. Use a forklift driver when the approved handling arrangement requires one.</td><td>Roll identity maintained; inspected, waiting and held material kept separate.</td></tr>\n<tr><td>Authorized QA reviewer</td><td>Review the completed report against the agreed buyer criteria. Record release, hold or rejection with reasons. Arrange additional inspection or supplier follow-up when required.</td><td>Named decision, date, evidence and clear warehouse disposition instruction.</td></tr>\n</tbody></table>";
export default function FabricInspectionJobCard() { return <div className="fabric-role-table" style={{background:"white",color:"#203448",padding:18,height:"100%"}}><style>{`.fabric-role-table table{width:100%;border-collapse:collapse;table-layout:fixed;font:17px/1.5 system-ui,sans-serif}.fabric-role-table th{text-align:left;background:#203448;color:white;padding:15px;font-size:15px;letter-spacing:.5px}.fabric-role-table td{vertical-align:top;padding:18px 15px;border-bottom:1px solid #dce5eb;overflow-wrap:break-word}.fabric-role-table th:first-child{width:24%}.fabric-role-table th:nth-child(2){width:50%}.fabric-role-table th:last-child{width:26%}.fabric-role-table td:first-child{font-weight:700}.fabric-role-table td:last-child{color:#536c7e}`}</style><div dangerouslySetInnerHTML={{__html:TABLE_HTML}} /></div>; }
